function item(topicId, num, topic, cat, vn, en, alts, hint) {
  const padNum = num < 10 ? '0' + num : '' + num;
  return {
    id: `${topicId}_${padNum}`,
    topic,
    vietnamese: vn,
    acceptedAnswers: [en, ...(alts || [])],
    standardEnglish: en,
    hint,
    category: cat
  };
}

